#include <array>
#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<string> titles(n);
    for (auto &s : titles) cin >> s;
    vector<array<int, 26>> next(1);
    next[0].fill(0);
    vector<long long> ends(1, 0);  // how many titles end at each trie node
    for (const string &s : titles) {
        int x = 0;
        for (char ch : s) {
            int c = ch - 'a';
            if (!next[x][c]) {
                next[x][c] = next.size();
                next.emplace_back();
                next.back().fill(0);
                ends.push_back(0);
            }
            x = next[x][c];
        }
        ends[x]++;
    }
    long long ans = 0;
    for (const string &s : titles) {
        int x = 0;
        for (char ch : s) {
            x = next[x][ch - 'a'];
            ans += ends[x];  // every title ending on this path is a prefix of s
        }
        ans--;  // s itself
    }
    cout << ans << '\n';
}

import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        String[] titles = new String[n];
        int total = 0;
        for (int i = 0; i < n; i++) {
            titles[i] = next();
            total += titles[i].length();
        }
        int[][] child = new int[total + 1][26];
        long[] ends = new long[total + 1];  // how many titles end at each trie node
        int nodes = 1;
        for (String s : titles) {
            int x = 0;
            for (int i = 0; i < s.length(); i++) {
                int c = s.charAt(i) - 'a';
                if (child[x][c] == 0) child[x][c] = nodes++;
                x = child[x][c];
            }
            ends[x]++;
        }
        long ans = 0;
        for (String s : titles) {
            int x = 0;
            for (int i = 0; i < s.length(); i++) {
                x = child[x][s.charAt(i) - 'a'];
                ans += ends[x];  // every title ending on this path is a prefix of s
            }
            ans--;  // s itself
        }
        System.out.println(ans);
    }
}

