import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func nextToken() string {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	titles := make([]string, n)
	for i := range titles {
		titles[i] = nextToken()
	}
	child := [][26]int32{{}}
	ends := []int64{0} // how many titles end at each trie node
	for _, s := range titles {
		x := 0
		for i := 0; i < len(s); i++ {
			c := s[i] - 'a'
			if child[x][c] == 0 {
				child[x][c] = int32(len(child))
				child = append(child, [26]int32{})
				ends = append(ends, 0)
			}
			x = int(child[x][c])
		}
		ends[x]++
	}
	var ans int64
	for _, s := range titles {
		x := 0
		for i := 0; i < len(s); i++ {
			x = int(child[x][s[i]-'a'])
			ans += ends[x] // every title ending on this path is a prefix of s
		}
		ans-- // s itself
	}
	fmt.Println(ans)
}
